using System.Text.RegularExpressions;
using Microsoft.AspNetCore.Hosting;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Shop.Modules.Catalog.Domain;
using Shop.Modules.Catalog.Infrastructure;
using Shop.Modules.Inventory;
using Shop.Modules.Sales;

namespace Shop.UiHarness;
internal static class ComparisonHarnessSeed
{
    internal static async Task RunAsync(IServiceProvider services,string database,string directory)
    {
        if(!services.GetRequiredService<IWebHostEnvironment>().IsDevelopment()||!Regex.IsMatch(database,"^SaymanTest_Ui_[a-f0-9]{32}$")||Path.GetFileName(directory)!=database)throw new InvalidOperationException("Fresh owned Development comparison QA required.");
        var db=services.GetRequiredService<CatalogDbContext>();var stock=services.GetRequiredService<InventoryDbContext>();var sales=services.GetRequiredService<SalesDbContext>();
        if(db.Database.GetDbConnection().Database!=database||stock.Database.GetDbConnection().Database!=database||sales.Database.GetDbConnection().Database!=database||await sales.ChargePolicies.AnyAsync()||await sales.OrderSettings.AnyAsync()||await sales.Orders.AnyAsync())throw new InvalidOperationException("Comparison seed cannot write main or configure financial policies.");
        var key=Guid.NewGuid().ToString("N");
        var descriptors=new[]{("memory","حافظه","Storage",AttributeDataType.Number,"GB"),("battery","باتری","Battery",AttributeDataType.Number,"%"),("5g","پشتیبانی 5G","5G support",AttributeDataType.Bool,""),("chip","پردازنده","Chipset",AttributeDataType.Text,""),("screen","نمایشگر","Screen",AttributeDataType.Select,""),("ports","ارتباط‌ها","Connectivity",AttributeDataType.MultiSelect,""),("size","اندازه نمایشگر","Screen size",AttributeDataType.Number,"inch"),("note","توضیح نمونه","Sample note",AttributeDataType.Text,""),("internal","غیرقابل‌مقایسه","Not comparable",AttributeDataType.Text,"")};
        var definitions=descriptors.Select((d,i)=>new AttributeDefinition{Id=key+"d"+i,Key="comparison-"+d.Item1+"-"+key,DataType=d.Item4,Unit=d.Item5,Translations=[new(){Locale="fa",Name=d.Item2,Unit=d.Item5},new(){Locale="en",Name=d.Item3,Unit=d.Item5}],Options=d.Item4 is AttributeDataType.Select or AttributeDataType.MultiSelect?[new(){Id=key+"o"+i+"a",Value="first",LabelFa=d.Item4==AttributeDataType.Select?"OLED":"USB-C",LabelEn=d.Item4==AttributeDataType.Select?"OLED":"USB-C"},new(){Id=key+"o"+i+"b",Value="second",LabelFa=d.Item4==AttributeDataType.Select?"IPS":"بلوتوث",LabelEn=d.Item4==AttributeDataType.Select?"IPS":"Bluetooth"}]:[]}).ToArray();
        var category=new Category{Id=key+"cat",Slug="comparison-phones-"+key,ImageUrl="/products/charger.svg",Translations=[new(){Locale="fa",Name="گوشی‌های نمونهٔ مقایسه"},new(){Locale="en",Name="Comparison sample phones"}],Attributes=definitions.Select((d,i)=>new CategoryAttribute{AttributeId=d.Id,SortOrder=i,IsComparable=i<8,IsFilterable=true,IsVariantAxis=i==0}).ToList()};
        var other=new Category{Id=key+"other",Slug="comparison-other-"+key,ImageUrl="/products/charger.svg",Translations=[new(){Locale="fa",Name="دستهٔ دیگر نمونه"},new(){Locale="en",Name="Other sample category"}]};
        var brand=new Brand{Id=key+"brand",Name="Comparison QA",Slug="comparison-brand-"+key};
        Product Make(string suffix,bool second=false)=>new(){Id=key+suffix,Slug="qa-compare-"+suffix.ToLowerInvariant()+"-"+key,CategoryId=category.Id,BrandId=brand.Id,Status="Published",Media=[new(){Url="/products/charger.svg"}],PurchaseMethods=[new(){MethodId="online"}],Translations=[new(){Locale="fa",Name="گوشی نمونهٔ مقایسه "+suffix,Description="دادهٔ مصنوعی فقط برای آزمون"},new(){Locale="en",Name="Comparison sample phone "+suffix,Description="Synthetic QA data only"}],Attributes=[new(){AttributeId=definitions[0].Id,ValueNumber=second?256:128},new(){AttributeId=definitions[1].Id,ValueNumber=second?95:100},new(){AttributeId=definitions[2].Id,ValueBool=!second},new(){AttributeId=definitions[3].Id,ValueTextFa=second?"تراشه ب":"تراشه آ",ValueTextEn=second?"Chip B":"Chip A"},new(){AttributeId=definitions[4].Id,ValueOptionId=definitions[4].Options[second?1:0].Id},new(){AttributeId=definitions[5].Id,Selections=definitions[5].Options.Take(second?1:2).Select(o=>new ProductAttributeSelection{OptionId=o.Id}).ToList()},new(){AttributeId=definitions[6].Id,ValueNumber=second?6.5m:6.7m},new(){AttributeId=definitions[7].Id,ValueTextFa="نمونه "+suffix,ValueTextEn="Sample "+suffix},new(){AttributeId=definitions[8].Id,ValueTextFa="نباید در مقایسه دیده شود",ValueTextEn="Must not appear in comparison"}],Variants=[new(){Id=key+suffix+"v1",Sku="CMP-"+suffix+"-128-"+key,PriceRial=second?123:689000000,LabelFa="۱۲۸ گیگ نمونه",LabelEn="128 GB sample",Color="#202020",ColorNameFa="مشکی",ColorNameEn="Black",WarrantyFa="گارانتی نمونهٔ اول",WarrantyEn="First sample warranty",Attributes=[new(){AttributeId=definitions[0].Id,ValueNumber=128}]},new(){Id=key+suffix+"v2",Sku="CMP-"+suffix+"-512-"+key,PriceRial=second?long.MaxValue:9007199254740993L,LabelFa="۵۱۲ گیگ نمونه",LabelEn="512 GB sample",Color="#eeeeee",ColorNameFa="سفید",ColorNameEn="White",WarrantyFa="گارانتی نمونهٔ دوم",WarrantyEn="Second sample warranty",Attributes=[new(){AttributeId=definitions[0].Id,ValueNumber=512}]}]};
        var a=Make("A");var b=Make("B",true);var hidden=Make("H");hidden.Status="Hidden";var mixed=Make("C");mixed.CategoryId=other.Id;mixed.Attributes.Clear();foreach(var v in mixed.Variants)v.Attributes.Clear();
        db.AttributeDefinitions.AddRange(definitions);db.Categories.AddRange(category,other);db.Brands.Add(brand);db.Products.AddRange(a,b,hidden,mixed);await db.SaveChangesAsync();
        foreach(var p in new[]{a,b,hidden,mixed})foreach(var v in p.Variants)stock.Stock.Add(new(){VariantId=v.Id,OnHand=(p==a&&v==a.Variants[1]||p==b&&v==b.Variants[0])?3:0});await stock.SaveChangesAsync();
        await UiHarnessProgram.WritePrivate(Path.Combine(directory,"comparison.json"),new{Database=database,SyntheticQaOnly=true,CategoryId=category.Id,OtherCategoryId=other.Id,ProductIds=new[]{a.Id,b.Id},HiddenProductId=hidden.Id,MixedProductId=mixed.Id,ProductSlugs=new[]{a.Slug,b.Slug},Variants=new[]{a,b}.Select(p=>new{ProductId=p.Id,Items=p.Variants.Select(v=>new{v.Id,v.Sku,PriceRial=v.PriceRial.ToString(System.Globalization.CultureInfo.InvariantCulture)})}),Attributes=definitions.Select((d,i)=>new{d.Id,d.Key,Comparable=i<8})});
    }
}
